<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {useRoute} from 'vue-router';import {api,clp,date,errorText} from '../api';import {useAuth} from '../stores/auth';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';
const route=useRoute(),auth=useAuth(),company=ref<any>(null),works=ref<any[]>([]),charges=ref<any[]>([]),docs=ref<any[]>([]),error=ref(''),tab=ref('summary'),edit=ref(false),busy=ref(false),form=ref<any>({});async function load(){error.value='';try{const id=Number(route.params.id);const [c,w,b,d]=await Promise.all([api.get('/companies/'+id),api.get('/works',{params:{company_id:id}}),api.get('/charges',{params:{company_id:id}}),api.get('/documents',{params:{company_id:id}})]);company.value=c.data;works.value=w.data;charges.value=b.data;docs.value=d.data;}catch(e){error.value=errorText(e);}}async function archive(){busy.value=true;try{await api.post(`/companies/${company.value.id}/archive`);await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}function openEdit(){form.value={...company.value};edit.value=true;}async function save(){busy.value=true;try{await api.put(`/companies/${company.value.id}`,form.value);edit.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(load);watch(()=>route.params.id,load);
</script>
<template><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="company"><PageHeading :title="company.trade_name||company.name" :subtitle="`${company.rut} · ${company.service}${company.archived_at?' · Archivada':''}`"><button v-if="auth.admin" class="button" @click="openEdit">Editar ficha</button><button v-if="auth.admin" class="button" :disabled="busy" @click="archive">{{company.archived_at?'Reactivar':'Archivar'}}</button></PageHeading><div class="filter-tabs tabs-large"><button v-for="t in [{id:'summary',name:'Resumen'},{id:'works',name:'Trabajos'},{id:'documents',name:'Documentos'},{id:'billing',name:'Honorarios'},{id:'contacts',name:'Contactos'}]" :key="t.id" @click="tab=t.id" :aria-pressed="tab===t.id">{{t.name}}</button></div><section class="panel"><div class="panel-heading"><h2>{{{summary:'Relación de trabajo',works:'Trabajos por período',documents:'Antecedentes solicitados',billing:'Honorarios y saldos',contacts:'Datos de contacto'}[tab]}}</h2></div><dl v-if="tab==='summary'" class="detail-grid"><div><dt>Razón social</dt><dd>{{company.name}}</dd></div><div><dt>Contador responsable</dt><dd>{{company.responsible?.name||'Sin asignar'}}</dd></div><div><dt>Servicio</dt><dd>{{company.service}}</dd></div><div><dt>Honorario de referencia</dt><dd>{{clp(company.monthly_fee)}}</dd></div><div><dt>Inicio de relación</dt><dd>{{date(company.starts_on)}}</dd></div><div><dt>Giro</dt><dd>{{company.business||'Sin registrar'}}</dd></div></dl><template v-if="tab==='works'"><div class="list-row" v-for="w in works" :key="w.id"><div><strong>{{w.title}}</strong><small>{{w.period}} · Fecha interna {{date(w.due_on)}}</small></div><StatusBadge :status="w.status"/></div><RouterLink class="panel-link" :to="`/works?company_id=${company.id}`">Abrir trabajos →</RouterLink></template><template v-if="tab==='documents'"><div class="list-row" v-for="d in docs" :key="d.id"><div><strong>{{d.title}}</strong><small>{{d.work?.period}}</small></div><StatusBadge :status="d.status"/></div><RouterLink class="panel-link" :to="`/documents?company_id=${company.id}`">Revisar documentos →</RouterLink></template><template v-if="tab==='billing'"><div class="list-row" v-for="b in charges" :key="b.id"><div><strong>{{b.period}} · {{clp(b.amount)}}</strong><small>Saldo {{clp(b.balance)}}</small></div><StatusBadge :status="b.payment_status"/></div></template><dl v-if="tab==='contacts'" class="detail-grid"><div><dt>Contacto</dt><dd>{{company.contact_name||'Sin registrar'}}</dd></div><div><dt>Correo</dt><dd>{{company.contact_email||'Sin registrar'}}</dd></div><div><dt>Teléfono</dt><dd>{{company.contact_phone||'Sin registrar'}}</dd></div><div><dt>Dirección</dt><dd>{{company.address||'Sin registrar'}}</dd></div></dl></section><Modal v-if="edit" title="Editar empresa" @close="edit=false"><form class="form-grid" @submit.prevent="save"><label>Razón social<input v-model="form.name" required></label><label>Nombre de fantasía<input v-model="form.trade_name"></label><label>RUT<input v-model="form.rut" required></label><label>Giro<input v-model="form.business"></label><label>Contacto<input v-model="form.contact_name"></label><label>Correo<input v-model="form.contact_email" type="email"></label><label>Teléfono<input v-model="form.contact_phone"></label><label>Dirección<input v-model="form.address"></label><label>Servicio<input v-model="form.service" required></label><label>Honorario CLP<input v-model.number="form.monthly_fee" type="number" min="0" required></label><p v-if="error" class="error span-two">{{error}}</p><div class="form-footer"><button class="button primary" :disabled="busy">Guardar cambios</button></div></form></Modal></template></template>
